function esc(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function sameId(a,b){return String(a)===String(b)}
function playlistPlaceholderMatchesFilm(placeholder,film){const keys=["wikidataId","tmdbId","imdbId"];return keys.some(key=>placeholder?.[key]&&film?.[key]&&String(placeholder[key]).trim().toLowerCase()===String(film[key]).trim().toLowerCase())}
function reconcileAllPlaylistPlaceholders(){const films=projects.flatMap(project=>project.films||[]);playlists.forEach(playlist=>{playlist.filmIds=[...new Set((playlist.filmIds||[]).map(String))];playlist.filmAssignments=playlist.filmAssignments||[];(playlist.placeholders||[]).forEach(placeholder=>{const match=films.find(film=>playlistPlaceholderMatchesFilm(placeholder,film));if(!match)return;placeholder.filmId=String(match.id);if(!playlist.filmIds.some(id=>sameId(id,match.id)))playlist.filmIds.push(match.id);if(!playlist.filmAssignments.some(entry=>sameId(entry.filmId,match.id)))playlist.filmAssignments.push({filmId:match.id,collectionNumber:placeholder.collectionNumber||""})})})}
function syncPlaylistCollectionNumbers(){playlists.forEach(playlist=>(playlist.placeholders||[]).forEach(placeholder=>{if(!placeholder.filmId)return;const assignment=(playlist.filmAssignments||[]).find(entry=>sameId(entry.filmId,placeholder.filmId));if(assignment)placeholder.collectionNumber=assignment.collectionNumber||""}))}
