function translateUiText(value){const clean=String(value).trim();if(UI_EN[clean])return String(value).replace(clean,UI_EN[clean]);let match=clean.match(/^(\d+) Titel$/);if(match)return `${match[1]} titles`;match=clean.match(/^(\d+) Film(e)?$/);if(match)return `${match[1]} ${match[1]==="1"?"film":"films"}`;match=clean.match(/^Fassung (\d+)$/);if(match)return `Edition ${match[1]}`;return value}
function translateUi(root=document){if(document.documentElement.lang!=="en")return;root.querySelectorAll?.("*").forEach(element=>{if(["SCRIPT","STYLE","TEXTAREA"].includes(element.tagName))return;[...element.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE&&node.nodeValue.trim()).forEach(node=>node.nodeValue=translateUiText(node.nodeValue));for(const attribute of ["placeholder","title","aria-label"]){const value=element.getAttribute(attribute);if(value)element.setAttribute(attribute,UI_PLACEHOLDERS_EN[value]||UI_EN[value]||value)}})}
function interfaceLanguage(){return document.documentElement.lang==="de"?"de":"en"}
function semanticLanguages(value){const values=Array.isArray(value)?value:String(value||"").split(/[,;/|]+/);const seen=new Set();return values.map(item=>{if(item&&typeof item==="object"&&item.code)return{id:item.id||"",code:String(item.code).toLowerCase(),label:item.label||""};const raw=String(item?.label||item||"").trim(),key=raw.toLocaleLowerCase("de"),known=LANGUAGE_CATALOG.find(language=>language.code===key||language.id.toLowerCase()===key||Object.values(language.labels||{}).some(label=>label.toLocaleLowerCase("de")===key)||(language.aliases||[]).includes(key));return known?{id:known.id,code:known.code}:{id:"",code:"",label:raw}}).filter(item=>{const key=item.id||item.code||item.label.toLocaleLowerCase("de");if(!key||seen.has(key))return false;seen.add(key);return true})}
function languageName(language){const known=LANGUAGE_CATALOG.find(item=>item.id===language.id||item.code===language.code);return known?.labels?.[interfaceLanguage()]||known?.labels?.en||language.label||language.code||language.id||""}
function languageText(value){return semanticLanguages(value).map(languageName).filter(Boolean).join(", ")}
function genreRecord(value){const key=String(value||"").trim().toLocaleLowerCase("de");return REFERENCE_CATALOG.genres.find(genre=>genre.key===key||Object.values(genre.labels||{}).some(label=>label.toLocaleLowerCase("de")===key)||(genre.aliases||[]).includes(key))}
function genreKey(value){const raw=String(value||"").trim();if(!raw)return"";if(raw.startsWith("custom:"))return raw;if(raw.toLocaleLowerCase("de")==="alle"||raw.toLocaleLowerCase("en")==="all")return"all";return genreRecord(raw)?.key||`custom:${raw.toLocaleLowerCase("de")}`}
function genreName(value){if(value==="all")return interfaceLanguage()==="de"?"Alle":"All";if(value==="series")return interfaceLanguage()==="de"?"Serien":"Series";const record=genreRecord(String(value).replace(/^custom:/,""));return record?.labels?.[interfaceLanguage()]||record?.labels?.en||String(value).replace(/^custom:/,"")}
function genreText(value){return String(value||"").split(",").map(item=>genreName(genreKey(item))).filter(Boolean).join(", ")}
function renderLanguageOptions(){$("languageOptions").innerHTML=LANGUAGE_CATALOG.map(language=>`<option value="${esc(language.labels?.[interfaceLanguage()]||language.code)}"></option>`).join("")}
function selectedFilmLocale(){const value=localStorage.getItem(FILM_METADATA_LANGUAGE_KEY)||"app";if(value==="app")return(document.documentElement.lang||"de")==="en"?"en-US":"de-DE";return value}
function supportedFilmLocales(){return [...$("filmMetadataLanguageSelect").options].map(option=>option.value).filter(locale=>locale!=="app"&&locale!=="original")}
function localizedFilm(film){const locale=selectedFilmLocale(),localized=locale==="original"?null:film.localizedMetadata?.[locale],display=localized?{...film,...localized}:{...film};if(film.originalCover)display.cover=film.originalCover;return display}
function posterStyle(film){const pair=huePairs[Math.abs(hash(film.title))%huePairs.length];return `--poster-a:${pair[0]};--poster-b:${pair[1]}`}
function hash(s){return [...s].reduce((a,c)=>((a<<5)-a+c.charCodeAt(0))|0,0)}
function genres(films){const playlistNames=new Set(playlists.map(playlist=>String(playlist.name||"").trim().toLocaleLowerCase()));return ["all",...new Set(films.flatMap(f=>String(f.genre||"").split(",").map(value=>value.trim()).filter(value=>value&&!playlistNames.has(value.toLocaleLowerCase())).map(genreKey).filter(Boolean)))]}
function catalogFilms(){let films=catalogProjectId==="all"?projects.flatMap(project=>project.films):projects.find(project=>project.id===catalogProjectId)?.films||[];if(catalogPlaylistId!=="all"){const playlist=playlists.find(item=>sameId(item.id,catalogPlaylistId)),ids=new Set((playlist?.filmIds||[]).map(String));films=films.filter(film=>ids.has(String(film.id)))}return films}
function filmLanguages(film){const found=new Map();filmCopies(film).forEach(copy=>semanticLanguages(copy.languages).forEach(language=>{const label=languageName(language),key=language.code||language.id||label.toLocaleLowerCase("de");if(!found.has(key))found.set(key,label)}));return [...found.entries()].map(([key,label])=>({key,label}))}
function filmSubtitles(film){const found=new Map();filmCopies(film).forEach(copy=>semanticLanguages(copy.subtitles).forEach(language=>{const label=languageName(language),key=language.code||language.id||label.toLocaleLowerCase("de");if(!found.has(key))found.set(key,label)}));return [...found.entries()].map(([key,label])=>({key,label}))}
function archiveSubtitleOptions(){const counts=new Map(),labels=new Map();projects.flatMap(project=>project.films).forEach(film=>filmSubtitles(film).forEach(({key,label})=>{counts.set(key,(counts.get(key)||0)+1);if(!labels.has(key))labels.set(key,label)}));return [...counts].map(([key,count])=>({key,label:labels.get(key),count})).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,"de"))}
function archiveLanguageOptions(){const counts=new Map(),labels=new Map();projects.flatMap(project=>project.films).forEach(film=>filmLanguages(film).forEach(({key,label})=>{counts.set(key,(counts.get(key)||0)+1);if(!labels.has(key))labels.set(key,label)}));return [...counts].map(([key,count])=>({key,label:labels.get(key),count})).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,"de",{sensitivity:"base"}))}
function renderCatalogLanguageFilters(){const options=archiveLanguageOptions(),available=new Set(options.map(option=>option.key)),previous=[...selectedCatalogLanguages];selectedCatalogLanguages=new Set(previous.filter(language=>available.has(language)));if(previous.length!==selectedCatalogLanguages.size)saveCatalogState();$("catalogLanguagesEmpty").hidden=options.length>0;$("catalogLanguageFilters").hidden=!options.length;$("catalogLanguageFilters").innerHTML=options.map(option=>`<label><input type="checkbox" value="${esc(option.key)}" ${selectedCatalogLanguages.has(option.key)?"checked":""}><span>${esc(option.label)}</span><small>${option.count}</small></label>`).join("")}
