function filteredFilms(){const films=catalogFilms().filter(f=>filmMatchesGenre(f)&&((selectedCatalogLanguages.size===0&&selectedCatalogSubtitles.size===0)||filmLanguages(f).some(language=>selectedCatalogLanguages.has(language.key))||filmSubtitles(f).some(subtitle=>selectedCatalogSubtitles.has(subtitle.key)))&&filmMatchesQuery(f,catalogSearchQuery));const locale=interfaceLanguage(),byTitle=(a,b)=>String(a.title||"").localeCompare(String(b.title||""),locale,{sensitivity:"base"}),byCollectionNumber=(a,b)=>{const aNumber=filmCollectionNumber(a),bNumber=filmCollectionNumber(b);if(!aNumber)return bNumber?1:byTitle(a,b);if(!bNumber)return -1;return aNumber.localeCompare(bNumber,locale,{numeric:true,sensitivity:"base"})||byTitle(a,b)},randomValue=film=>{const id=String(film.id);if(!catalogRandomOrder.has(id))catalogRandomOrder.set(id,Math.random());return catalogRandomOrder.get(id)};return films.sort((a,b)=>catalogSort==="random"?randomValue(a)-randomValue(b):catalogSort==="collection-number"?byCollectionNumber(a,b):catalogSort==="year-desc"?(Number(b.year)||0)-(Number(a.year)||0)||byTitle(a,b):catalogSort==="year-asc"?(Number(a.year)||9999)-(Number(b.year)||9999)||byTitle(a,b):catalogSort==="genre"?genreText(a.genre).localeCompare(genreText(b.genre),locale,{sensitivity:"base"})||byTitle(a,b):byTitle(a,b))}
