function renderPlaylists(){const active=playlists.find(item=>item.id===activePlaylistId);els.playlistList.innerHTML=playlists.map(item=>`<div class="project-row ${item.id===activePlaylistId?"is-active":""}"><button class="project-item" type="button" data-playlist-id="${item.id}"><span>${esc(item.name)}</span><small>${playlistEntryCount(item)}</small></button><div class="project-row-menu-wrap"><button class="project-row-menu-button" type="button" data-playlist-row-menu="${item.id}" aria-label="Menü für ${esc(item.name)} öffnen" aria-expanded="false">⋮</button><div class="project-row-menu" data-playlist-row-popup="${item.id}" hidden><button type="button" data-delete-playlist="${item.id}">Löschen</button></div></div></div>`).join("");els.playlistTitle.textContent=active?.name||"Playlisten";const activeCount=active?playlistEntryCount(active):0;els.playlistSummary.textContent=active?`${activeCount} ${activeCount===1?"Film":"Filme"} · ${active.description||"Ohne Beschreibung"}`:"Noch keine Playlist angelegt.";$("playlistEmptyTitle").textContent=active?"Diese Playlist ist noch leer.":"Filme für einen Abend zusammenstellen";$("playlistEmptyText").textContent=active?"Die Filmzuordnung folgt direkt aus dem Filmarchiv.":"Lege links deine erste Playlist an."}
