function updateGenreOverflow(){cancelAnimationFrame(genreOverflowFrame);genreOverflowFrame=requestAnimationFrame(()=>{if(!genreFiltersVisible){els.genreToggle.hidden=true;return}const less=interfaceLanguage()==="de"?"Weniger Genres":"Fewer genres",all=interfaceLanguage()==="de"?"Alle Genres":"All genres",more=interfaceLanguage()==="de"?"Mehr Genres":"More genres";els.genreFilters.classList.remove("is-expanded");if(isNeonTheme()){const hasSecondary=Boolean(els.genreFilters.querySelector(".neon-secondary-genre"));els.genreFilters.classList.toggle("is-expanded",genresExpanded&&hasSecondary);els.genreToggle.hidden=!hasSecondary;els.genreToggle.setAttribute("aria-expanded",String(genresExpanded&&hasSecondary));els.genreToggle.innerHTML=genresExpanded&&hasSecondary?`${less} <span aria-hidden="true">⌃</span>`:`${all} <span aria-hidden="true">⌄</span>`;return}const overflowing=els.genreFilters.scrollHeight>els.genreFilters.clientHeight+1;if(genresExpanded&&overflowing)els.genreFilters.classList.add("is-expanded");els.genreToggle.hidden=!overflowing;els.genreToggle.setAttribute("aria-expanded",String(genresExpanded&&overflowing));els.genreToggle.innerHTML=genresExpanded&&overflowing?`${less} <span aria-hidden="true">⌃</span>`:`${more} <span aria-hidden="true">⌄</span>`})}
