function linkifyDetailCast(){const host=document.querySelector(".detail-cast:not([data-linked])");if(!host)return;host.dataset.linked="true";const names=String(host.textContent||"").replace(/^Mit\s+|^Cast\s+/i,"").split(/\s*[,;]\s*/).map(name=>name.trim()).filter(Boolean),label=host.querySelector("strong")?.cloneNode(true)||document.createElement("strong");host.replaceChildren(label,document.createTextNode(" "));names.forEach((name,index)=>{if(index)host.append(document.createTextNode(", "));const button=document.createElement("button");button.type="button";button.className="detail-person-link";button.dataset.personSearch=name;button.textContent=name;button.title=`Nach ${name} suchen`;host.append(button)})}
