function updateMediaTypeFields(){const series=selectedMediaType()==="tv",english=interfaceLanguage()==="en",text=(de,en)=>english?en:de;$('filmYearLabel').textContent=series?text("Erstausstrahlung","First aired"):text("Jahr","Year");$('filmRuntimeLabel').textContent=series?text("Folgenlaufzeit (h:mm:ss)","Episode runtime (h:mm:ss)"):text("Laufzeit (h:mm:ss)","Runtime (h:mm:ss)");$('filmDirectorLabel').textContent=series?text("Konzept / Schöpfer","Created by"):text("Regie","Director");document.querySelectorAll('[data-series-field]').forEach(field=>field.hidden=!series);const existing=Boolean($('filmId').value&&activeProject().films.some(film=>sameId(film.id,$('filmId').value)));$('filmDialogTitle').textContent=series?(existing?text("Serie bearbeiten","Edit series"):text("Serie anlegen","Add series")):(existing?text("Film bearbeiten","Edit film"):text("Film anlegen","Add film"));$('deleteFilmButton').textContent=series?text("Serie löschen","Delete series"):text("Film löschen","Delete film")}
