function mergeFilmIntoProject(target,film){const identifiers=["tmdbId","imdbId","wikidataId"],hasId=identifiers.some(key=>String(film[key]||"").trim());if(!hasId){target.films.unshift(film);return film}const matches=target.films.filter(candidate=>identifiers.some(key=>film[key]&&candidate[key]&&String(film[key])===String(candidate[key])&&(key!=="tmdbId"||filmMediaType(film)===filmMediaType(candidate))));if(!matches.length){target.films.unshift(film);return film}const base=matches[0],copiesByLink=new Map();[...filmCopies(base),...filmCopies(film)].forEach(copy=>{const link=String(copy.link||"").trim(),key=link||`missing-${copiesByLink.size}`;if(!copiesByLink.has(key))copiesByLink.set(key,{...copy})});base.copies=[...copiesByLink.values()];base.localizedMetadata={...(base.localizedMetadata||{}),...(film.localizedMetadata||{})};identifiers.forEach(key=>{if(!base[key]&&film[key])base[key]=film[key]});const protectedFields=new Set(["id","copies","link","status","localizedMetadata","mediaType",...identifiers]);Object.keys(base).forEach(key=>{if(!protectedFields.has(key)&&base[key]&&film[key]&&String(base[key])!==String(film[key]))base[key]=""});target.films=target.films.filter(candidate=>candidate===base||!matches.includes(candidate));return base}
function dropFilmOnProject(event){const row=projectDropRow(event.target),targetId=row?.querySelector("[data-project-id]")?.dataset.projectId,reference=draggedFilmReference;event.preventDefault();clearFilmDropState();draggedFilmReference=null;if(!reference||!targetId||sameId(targetId,reference.projectId))return;const source=projects.find(project=>sameId(project.id,reference.projectId)),target=projects.find(project=>sameId(project.id,targetId)),filmIndex=source?.films.findIndex(film=>sameId(film.id,reference.filmId))??-1;if(!source||!target||filmIndex<0)return;const [film]=source.films.splice(filmIndex,1);mergeFilmIntoProject(target,film);save();render();toast(`„${film.title}“ nach „${target.name}“ verschoben`)}
