function normalizeRuntime(value){if(value===""||value===null||value===undefined)return "";if(typeof value==="number"||/^\d+(?:\.\d+)?$/.test(String(value).trim())){const seconds=Math.round(Number(value)*60);const hours=Math.floor(seconds/3600);const minutes=Math.floor(seconds%3600/60);return `${hours}:${String(minutes).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`}const match=String(value).trim().match(/^(\d{1,3}):([0-5]\d):([0-5]\d)$/);return match?`${Number(match[1])}:${match[2]}:${match[3]}`:""}
