function editProjectField(id,field,label){const p=projects.find(x=>sameId(x.id,id));if(!p)return;const value=window.prompt(label,p[field]||"");if(value===null)return;p[field]=value.trim();save();render();toast("Projekt aktualisiert")}function deleteProject(id,holdComplete=document.querySelector(`[data-delete-project="${CSS.escape(String(id))}"]`)?.style.getPropertyValue("--hold-progress")==="100%"){if(!holdComplete)return;const project=projects.find(item=>item.id===id);if(!project)return;if(projects.length===1){toast("Das letzte Projekt kann nicht gelöscht werden");return}projects=projects.filter(item=>item.id!==id);if(activeProjectId===id)activeProjectId=projects[0].id;if(catalogProjectId===id){catalogProjectId="all";activeGenre="all";saveCatalogState()}save();render();toast("Projekt gelöscht")}
let editingCopies=[];
let editingLocalizedMetadata={};
let editingOriginalCover="";
let editingPlaylistIds=new Set();
let editingPlaylistNumbers=new Map();
function filmCopies(film){if(Array.isArray(film?.copies))return film.copies.map(copy=>({...copy,title:copy.title||copy.label||"",access:["public","password"].includes(copy.access)?copy.access:"private",password:String(copy.password||"")}));return film?.link?[{id:uid("copy"),title:"Fassung 1",link:film.link,languages:"",resolution:"",quality:"",status:film.status||"verfügbar",access:"private",password:""}]:[]}
function setFilmTab(tab){const active=["general","copies","playlists"].includes(tab)?tab:"general";document.querySelectorAll("[data-film-tab]").forEach(button=>{const selected=button.dataset.filmTab===active;button.classList.toggle("is-active",selected);button.setAttribute("aria-selected",String(selected))});$("filmGeneralPanel").hidden=active!=="general";$("filmCopiesPanel").hidden=active!=="copies";$("filmPlaylistsPanel").hidden=active!=="playlists"}
function updateFilmPlaylistCount(){const checked=[$("filmPlaylistChecklist")].flatMap(root=>[...root.querySelectorAll('[data-playlist-check]:checked')]);$("filmPlaylistCount").textContent=checked.length}
function playlistNumber(playlist,filmId){return String((playlist.filmAssignments||[]).find(entry=>sameId(entry.filmId,filmId))?.collectionNumber||"")}
function renderFilmPlaylistChecklist(){$("filmPlaylistsEmpty").hidden=playlists.length>0;$("filmPlaylistChecklist").hidden=!playlists.length;$("filmPlaylistChecklist").innerHTML=playlists.map(playlist=>{const id=String(playlist.id),checked=editingPlaylistIds.has(id);return `<div class="film-playlist-option"><label class="playlist-check-main"><input data-playlist-check type="checkbox" value="${esc(id)}" ${checked?"checked":""}><span><strong>${esc(playlist.name)}</strong><small>${playlist.filmIds?.length||0} ${playlist.filmIds?.length===1?"Film":"Filme"}</small></span></label><label class="playlist-number-field"><span>Sammlungsnummer</span><input data-playlist-number maxlength="6" pattern="[A-Za-z0-9]{0,6}" inputmode="text" value="${esc(editingPlaylistNumbers.get(id)||"")}" placeholder="ABC123"></label></div>`}).join("");$("filmPlaylistChecklist").querySelectorAll("[data-playlist-check]").forEach(input=>input.addEventListener("change",updateFilmPlaylistCount));$("filmPlaylistChecklist").querySelectorAll("[data-playlist-number]").forEach(input=>input.addEventListener("input",()=>{input.value=input.value.replace(/[^A-Za-z0-9]/g,"").slice(0,6)}));updateFilmPlaylistCount()}
function readFilmPlaylistChecklist(){editingPlaylistIds=new Set();editingPlaylistNumbers=new Map();$("filmPlaylistChecklist").querySelectorAll(".film-playlist-option").forEach(row=>{const checkbox=row.querySelector("[data-playlist-check]"),number=row.querySelector("[data-playlist-number]").value.trim();if(checkbox.checked){editingPlaylistIds.add(String(checkbox.value));editingPlaylistNumbers.set(String(checkbox.value),number)}})}
function readCopyEditor(){editingCopies=[...$("filmCopiesList").querySelectorAll("[data-copy-id]")].map(row=>({id:row.dataset.copyId,title:row.querySelector('[data-copy-field="title"]').value.trim(),link:row.querySelector('[data-copy-field="link"]').value.trim(),access:row.querySelector('[data-copy-field="access"]').value,password:row.querySelector('[data-copy-field="password"]').value,languages:semanticLanguages(row.querySelector('[data-copy-field="languages"]').value),subtitles:semanticLanguages(row.querySelector('[data-copy-field="subtitles"]').value),resolution:row.querySelector('[data-copy-field="resolution"]').value,quality:row.querySelector('[data-copy-field="quality"]').value,status:row.querySelector('[data-copy-field="status"]').value}))}
function renderCopyEditor(){$("filmCopyCount").textContent=editingCopies.length;$("filmCopiesEmpty").hidden=editingCopies.length>0;$("filmCopiesList").innerHTML=editingCopies.map((copy,index)=>`<section class="film-copy" data-copy-id="${esc(copy.id)}"><div class="film-copy-head"><strong>Fassung ${index+1}</strong><button type="button" data-remove-copy="${esc(copy.id)}" aria-label="Fassung ${index+1} entfernen">Entfernen</button></div><div class="copy-grid"><label>Quelle<input data-copy-field="title" maxlength="160" value="${esc(copy.title||copy.label||"")}" placeholder="z. B. Deutsche Kinofassung"></label><label>Sprache(n)<input data-copy-field="languages" maxlength="120" value="${esc(languageText(copy.languages))}" list="languageOptions" placeholder="Deutsch, Englisch"></label><label>Untertitel<input data-copy-field="subtitles" maxlength="120" value="${esc(languageText(copy.subtitles))}" list="languageOptions" placeholder="Deutsch, Englisch, keine"></label><div class="copy-link-row span-2"><label>Link zum Film<input data-copy-field="link" type="url" value="${esc(copy.link||"")}" placeholder="https://… oder file:///…"></label><label>Zugriff<select data-copy-field="access"><option value="private" ${copy.access!=="public"&&copy.access!=="password"?"selected":""}>Privates Archiv · erworben</option><option value="public" ${copy.access==="public"?"selected":""}>Frei zugänglich</option><option value="password" ${copy.access==="password"?"selected":""}>Zugänglich mit Passwort</option></select></label></div><label class="copy-password-field span-2" ${copy.access==="password"?"":"hidden"}>Passwort<input data-copy-field="password" type="password" value="${esc(copy.password||"")}" autocomplete="off" placeholder="Passwort für den Link"></label><label>Auflösung<select data-copy-field="resolution"><option value="">Nicht angegeben</option>${["4K / UHD","1080p","720p","576p","480p","Andere"].map(value=>`<option ${copy.resolution===value?"selected":""}>${value}</option>`).join("")}</select></label><label>Qualität<select data-copy-field="quality"><option value="">Nicht bewertet</option>${["Hervorragend","Sehr gut","Gut","Akzeptabel","Schlecht"].map(value=>`<option ${copy.quality===value?"selected":""}>${value}</option>`).join("")}</select></label><label>Status<select data-copy-field="status"><option value="verfügbar" ${copy.status==="verfügbar"?"selected":""}>Verfügbar</option><option value="prüfen" ${copy.status==="prüfen"?"selected":""}>Link prüfen</option><option value="nicht verfügbar" ${copy.status==="nicht verfügbar"?"selected":""}>Nicht verfügbar</option></select><small class="status-availability-note">Die Verfügbarkeit kann je nach Anbieter zeitweise schwanken.</small></label></div></section>`).join("");$("filmCopiesList").querySelectorAll('[data-copy-field="access"]').forEach(select=>select.addEventListener("change",()=>{select.closest(".film-copy").querySelector(".copy-password-field").hidden=select.value!=="password"}));$("filmCopiesList").querySelectorAll("[data-remove-copy]").forEach(button=>button.addEventListener("click",()=>{readCopyEditor();editingCopies=editingCopies.filter(copy=>!sameId(copy.id,button.dataset.removeCopy));renderCopyEditor()}))}
function addFilmCopy(){readCopyEditor();editingCopies.push({id:uid("copy"),title:`Fassung ${editingCopies.length+1}`,link:"",access:"private",password:"",languages:"",subtitles:"",resolution:"",quality:"",status:"verfügbar"});renderCopyEditor();setFilmTab("copies")}
