function youtubeVideoId(value){try{const url=new URL(value);if(url.hostname.includes("youtu.be"))return url.pathname.slice(1).split("/")[0];if(url.hostname.includes("youtube.com")){if(url.pathname.startsWith("/embed/"))return url.pathname.split("/")[2];if(url.pathname.startsWith("/shorts/"))return url.pathname.split("/")[2];return url.searchParams.get("v")||""}}catch{}return ""}
