function playlistPickerFilms(query=""){const needle=String(query).trim().toLowerCase();return projects.flatMap(project=>(project.films||[]).map(film=>({film,project}))).filter(({film})=>!needle||filmMatchesQuery(film,needle)).sort((a,b)=>String(a.film.title||"").localeCompare(String(b.film.title||""),interfaceLanguage(),{sensitivity:"base"}))}
