let editingPlaylistEntryIndex=null;
let editingPlaylistDirectFilmId="";
function preferredPlaylistIdentifier(film){if(film?.tmdbId)return String(film.tmdbId);if(film?.imdbId)return String(film.imdbId);if(film?.wikidataId)return String(film.wikidataId);return""}
function parsePlaylistIdentifier(raw){const value=String(raw||"").trim();if(/^tt\d+$/i.test(value))return{key:"imdbId",value:value.toLowerCase()};if(/^Q\d+$/i.test(value))return{key:"wikidataId",value:value.toUpperCase()};if(/^\d+$/.test(value))return{key:"tmdbId",value};return null}
