function openPlaylistFilmPicker(){const playlist=playlists.find(item=>sameId(item.id,activePlaylistId));if(!playlist){toast("Bitte zuerst eine Playlist auswählen");return}selectedPlaylistFilmId="";editingPlaylistEntryIndex=null;editingPlaylistDirectFilmId="";$("playlistEntryDelete").hidden=true;$("playlistEntrySave").textContent="Zur Playlist hinzufügen";$("playlistFilmDialogTitle").textContent=`Film zu „${playlist.name}“ hinzufügen`;$("playlistFilmSearch").value="";$("playlistEntryIdentifier").value="";$("playlistEntryDetails").value="";$("playlistEntryNumber").value="";setPlaylistFilmTab("archive");renderPlaylistFilmPicker();$("playlistFilmDialog").showModal();setTimeout(()=>$("playlistFilmSearch").focus(),0)}
