async function importProject(file){try{const data=JSON.parse(await file.text());const p=["videothek-project","filmmap-project"].includes(data?.format)||data?.project?.name?data.project:data;if(!p||typeof p.name!=="string"||!Array.isArray(p.films))throw new Error();const imported={...p,id:uid("projekt"),name:`${p.name} (Import)`,films:[]};p.films.map(f=>({...f,id:uid("film")})).forEach(f=>mergeFilmIntoProject(imported,f));projects.push(imported);activeProjectId=imported.id;save();render();toast("Projekt importiert")}catch{toast("Diese Datei ist kein gültiges Videothek-Projekt")}}
