const wait=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
async function syncFilmMetadata(){const locale=selectedFilmLocale();if(locale==="original"){toast("Für die Originalsprache ist keine Synchronisierung erforderlich");return}if(!tmdbToken){toast("Bitte zuerst den TMDB-Token hinterlegen");return}const films=projects.flatMap(project=>project.films).filter(film=>film.tmdbId&&(!film.localizedMetadata?.[locale]||!film.originalCover)),progress=$("filmMetadataSyncProgress"),bar=progress.querySelector("progress"),label=progress.querySelector("small"),button=$("syncFilmMetadataButton");progress.hidden=false;button.disabled=true;let completed=0,failed=0;for(const film of films){label.textContent=`${completed} / ${films.length}`;try{const mediaType=filmMediaType(film);let details;try{details=await fetchTmdb(`/${mediaType}/${encodeURIComponent(film.tmdbId)}`,{language:locale,append_to_response:"images",include_image_language:`${locale.split("-")[0]},null`})}catch(error){if(error.message!=="tmdb-429")throw error;await wait(2500);details=await fetchTmdb(`/${mediaType}/${encodeURIComponent(film.tmdbId)}`,{language:locale})}film.localizedMetadata={...(film.localizedMetadata||{}),[locale]:localizedTmdbMetadata(details,mediaType)};if(!film.originalCover){film.originalCover=await fetchOriginalTmdbCover(film.tmdbId,details.original_language,film.cover||film.localizedMetadata[locale].cover,mediaType);film.cover=film.originalCover}}catch{failed++}completed++;bar.value=films.length?completed/films.length*100:100;label.textContent=`${completed} / ${films.length}`;save();await wait(150)}button.disabled=false;render();toast(films.length?`${completed-failed} Sprachvarianten synchronisiert${failed?`, ${failed} fehlgeschlagen`:""}`:"Alle Sprachvarianten sind bereits vorhanden")}
