document.addEventListener("keydown",event=>{if(event.key!=="Tab")return;const drawer=$("catalogDrawer");if(drawer.classList.contains("is-open")){event.preventDefault();setCatalogDrawer(false);$("catalogMenuButton").focus();return}if(document.activeElement===document.body||document.activeElement===$("catalogMenuButton")){event.preventDefault();setCatalogDrawer(true)}});
