document.querySelectorAll("[data-film-id]").forEach(input=>input.addEventListener("input",updateIdentifierStatuses));document.querySelectorAll('input[name="filmMediaType"]').forEach(input=>input.addEventListener("change",()=>{updateMediaTypeFields();tmdbSearchResults=[];$("tmdbResults").innerHTML="";$("tmdbResults").hidden=true;$("tmdbStatus").textContent=selectedMediaType()==="tv"?"Seriensuche ist ausgewählt. Vorhandene Eingaben bleiben erhalten.":"Filmsuche ist ausgewählt. Vorhandene Eingaben bleiben erhalten."}));let tmdbIdLookupTimer=null;$("filmTmdbId").addEventListener("input",()=>{clearTimeout(tmdbIdLookupTimer);const id=$("filmTmdbId").value.trim();if(!/^\d+$/.test(id))return;tmdbIdLookupTimer=setTimeout(async()=>{try{const requested=selectedFilmLocale(),locale=requested==="original"?(interfaceLanguage()==="de"?"de-DE":"en-US"):requested,mediaType=selectedMediaType(),details=await fetchTmdb(`/${mediaType}/${encodeURIComponent(id)}`,{language:locale});renderTmdbResults([details]);$("tmdbStatus").textContent=`${mediaType==="tv"?"Serie":"Film"} gefunden. Bitte auswählen, um die Daten zu übernehmen.`}catch{$("tmdbStatus").textContent="Keine passende TMDB-ID gefunden."}},350)});
