els.projectList.addEventListener("dragstart",event=>{if(event.target.closest(".project-row-menu-wrap")){event.preventDefault();event.stopImmediatePropagation()}},{capture:true});
let projectDeleteHoldTimer=null;els.projectList.addEventListener("pointerdown",e=>{const b=e.target.closest("[data-delete-project]");if(!b)return;let n=0;b.style.setProperty("--hold-progress","0%");projectDeleteHoldTimer=setInterval(()=>{n+=10;b.style.setProperty("--hold-progress",n+"%");if(n>=100){clearInterval(projectDeleteHoldTimer);projectDeleteHoldTimer=null;deleteProject(b.dataset.deleteProject)}},50)});["pointerup","pointerleave","pointercancel"].forEach(t=>els.projectList.addEventListener(t,()=>{if(projectDeleteHoldTimer){clearInterval(projectDeleteHoldTimer);projectDeleteHoldTimer=null}}));els.projectList.addEventListener("dragstart",e=>{const r=e.target.closest("[data-project-drag]");if(r)e.dataTransfer.setData("text/project",r.dataset.projectDrag)});els.projectList.addEventListener("dragover",e=>{if(e.dataTransfer.types.includes("text/project"))e.preventDefault()});els.projectList.addEventListener("drop",e=>{const sourceId=e.dataTransfer.getData("text/project"),target=e.target.closest("[data-project-drag]"),targetId=target?.dataset.projectDrag;if(!sourceId||!targetId||sourceId===targetId)return;const source=projects.find(x=>x.id===sourceId),dest=projects.find(x=>x.id===targetId);if(!source||!dest)return;if(!confirm(`Möchten Sie die Projekte „${source.name}" und „${dest.name}" zusammenlegen? Alle Filme aus „${source.name}" werden in „${dest.name}" übernommen.`))return;dest.films.push(...source.films);projects=projects.filter(x=>x.id!==sourceId);if(activeProjectId===sourceId)activeProjectId=targetId;save();render();toast("Projekte zusammengelegt")});els.projectList.addEventListener("dragover",dragFilmOverProject);
function cancelProjectDeleteHold(button=null){if(projectDeleteHoldTimer){clearInterval(projectDeleteHoldTimer);projectDeleteHoldTimer=null}(button?[button]:els.projectList.querySelectorAll("[data-delete-project]")).forEach(item=>item.style.setProperty("--hold-progress","0%"))}
els.projectList.addEventListener("pointerout",event=>{const button=event.target.closest("[data-delete-project]");if(button&&!button.contains(event.relatedTarget))cancelProjectDeleteHold(button)});
document.addEventListener("pointerup",()=>cancelProjectDeleteHold(),true);
document.addEventListener("pointercancel",()=>cancelProjectDeleteHold(),true);
